let detectedTty = null;
try {
  const { execSync } = require("child_process");
  let walkPid = process.pid;
  for (let i = 0; i < 8; i++) {
    const info = execSync(`ps -o tty=,ppid= -p ${walkPid}`, { timeout: 1000 }).toString().trim();
    const parts = info.split(/\s+/);
    const tty = parts[0], ppid = parseInt(parts[1]);
    if (tty && tty !== "??" && tty !== "?") { detectedTty = `/dev/${tty}`; break; }
    if (!ppid || ppid <= 1) break;
    walkPid = ppid;
  }
} catch {}

function collectEnv() {
  const env = {};
  for (const k of ENV_KEYS) { if (process.env[k]) env[k] = process.env[k]; }
  if (process.env[`${_VI_ENV_PREFIX}_CLIENT`] === "desktop" && _VI_DESKTOP_BUNDLE_ID && !env.__CFBundleIdentifier) {
    env.__CFBundleIdentifier = _VI_DESKTOP_BUNDLE_ID;
  }
  return env;
}

export default async ({ client, serverUrl, directory }) => {
  const pid = process.pid;
  const serverOrigin = serverUrl?.origin || "http://127.0.0.1:4096";
  const serverPort = parseInt(serverUrl?.port) || 4096;

  function buildHeaders(cwd) {
    const headers = { "Content-Type": "application/json" };
    if (_AUTH_HEADER) headers.Authorization = _AUTH_HEADER;
    const dir = cwd || directory;
    if (dir) headers[_VI_DIRECTORY_HEADER] = encodeURIComponent(dir);
    return headers;
  }

  async function postReply(path, body, cwd) {
    try {
      const response = await fetch(`${serverOrigin}${path}`, {
        method: "POST", headers: buildHeaders(cwd), body: JSON.stringify(body),
      });
      if (response?.ok) return response;
    } catch {}
    const shouldUseClientFallback = !_AUTH_HEADER && serverPort === 4096;
    if (!shouldUseClientFallback) return null;
    try {
      const rawClient = client?._client;
      if (!rawClient?.post) return null;
      return await rawClient.post({ url: path, headers: buildHeaders(cwd), body });
    } catch { return null; }
  }

  async function fetchSessionInfo(sessionId, cwd) {
    const path = `/session/${encodeURIComponent(sessionId)}`;
    try {
      const response = await fetch(`${serverOrigin}${path}`, {
        method: "GET", headers: buildHeaders(cwd),
      });
      if (response?.ok) return await response.json();
    } catch {}
    const shouldUseClientFallback = !_AUTH_HEADER && serverPort === 4096;
    if (!shouldUseClientFallback) return null;
    try {
      const rawClient = client?._client;
      if (!rawClient?.get) return null;
      const result = await rawClient.get({ url: path, headers: buildHeaders(cwd) });
      return result?.data || result || null;
    } catch { return null; }
  }

  const seenEvents = new Map();
  const partBuffers = new Map();
  const assistantText = new Map();
  const fetchedInfo = new Map();
  
  const sessionCwd = new Map();

  function rememberSessionCwd(info) {
    if (!info?.id || !info.directory) return;
    sessionCwd.set(info.id, String(info.directory).slice(0, 4096));
    if (sessionCwd.size > 200) sessionCwd.delete(sessionCwd.keys().next().value);
  }

  
  function cleanupSeen(now) {
    if (seenEvents.size <= 500) return;
    const cutoff = now - 10 * 60 * 1000;
    for (const [key, ts] of seenEvents) {
      if (ts < cutoff || seenEvents.size > 800) seenEvents.delete(key);
      if (seenEvents.size <= 500) break;
    }
  }

  function eventKey(ev) {
    if (ev?.id) return `id:${ev.id}`;
    const p = ev?.properties || {};
    const part = p.part || {};
    const status = p.status?.type || part.state?.status || "";
    return [
      "fallback", ev?.type || "", p.sessionID || p.info?.sessionID || part.sessionID || p.info?.id || "",
      p.messageID || p.info?.id || part.messageID || "", p.partID || part.id || p.id || "", status,
    ].join(":");
  }

  function shouldProcessEvent(ev) {
    const key = eventKey(ev);
    if (!key) return true;
    if (seenEvents.has(key)) return false;
    const now = Date.now();
    seenEvents.set(key, now);
    cleanupSeen(now);
    return true;
  }

  function normalizeSyncEventType(type) {
    return (type || "").replace(/\.\d+$/, "");
  }

  function syncEventToBusEvent(syncEvent) {
    const type = normalizeSyncEventType(syncEvent?.type);
    if (!isObserved(type) && !APPROVAL_TYPES.has(type)) return null;
    return { id: syncEvent.id, type, properties: syncEvent.data || {} };
  }

  function isObserved(type) {
    return OBSERVED_TYPES.has(type);
  }

  
  function sessionOf(ev) {
    const p = ev.properties || {};
    return p.info?.sessionID || p.sessionID || p.part?.sessionID || p.info?.id || "";
  }

  
  function absorbDelta(p) {
    if (!p?.sessionID || !p?.partID || p.field !== "text") return;
    const key = `${p.sessionID}:${p.partID}`;
    const current = partBuffers.get(key) || "";
    if (current.length >= SNAPSHOT_CHAR_LIMIT) return;
    const next = (current + (p.delta || "")).slice(0, SNAPSHOT_CHAR_LIMIT);
    partBuffers.set(key, next);
    if (partBuffers.size > 200) partBuffers.delete(partBuffers.keys().next().value);
    assistantText.set(p.sessionID, next);
    if (assistantText.size > 200) assistantText.delete(assistantText.keys().next().value);
  }

  
  function isSyncDelivery(ev) {
    if (!SYNC_DELIVERY_TYPES.has(ev.type)) return false;
    if (ev.type !== "message.part.updated") return true;
    return SYNC_DELIVERY_PART_TYPES.has(ev.properties?.part?.type);
  }

  function wantsSnapshot(ev) {
    if (!SNAPSHOT_TYPES.has(ev.type)) return false;
    if (ev.type !== "message.part.updated") return true;
    return SNAPSHOT_PART_TYPES.has(ev.properties?.part?.type);
  }

  
  function projectKeys(source, keys) {
    if (!source || typeof source !== "object" || Array.isArray(source)) return {};
    const out = {};
    for (const k of keys) { if (source[k] !== undefined) out[k] = source[k]; }
    return out;
  }

  
  function envelope(ev, tail, hydration) {
    const key = String(sessionOf(ev) || "");
    if (!key) return null;
    const header = projectKeys(ev.properties?.info, HEADER_KEYS);
    
    const transport = {
      ppid: pid,
      cwd: directory,
      env: collectEnv(),
      tty: detectedTty,
      server_port: serverPort,
    };
    if (hydration) transport.hydration = true;
    const snapshot = tail ? assistantText.get(key) : null;
    if (snapshot) transport.assistant_text = snapshot;
    const info = fetchedInfo.get(key);
    if (info) transport.session_info = info;
    const body = {
      _vibe_wire: WIRE,
      _source: _VI_SOURCE,
      _session_key: key,
      _transport: transport,
      _raw: { header, event: { type: ev.type, data: ev.properties || {} } },
    };
    
    try {
      if (Buffer.byteLength(JSON.stringify(body._raw)) > RAW_LIMIT) {
        body._raw = { header: {}, event: { type: ev.type } };
        body._truncated = true;
      }
    } catch {
      body._raw = { header: {}, event: { type: ev.type } };
      body._truncated = true;
    }
    return body;
  }

  
  function serializeEnvelope(body) {
    const encode = () => { try { return JSON.stringify(body); } catch { return null; } };
    let text = encode();
    if (text === null) return null;
    if (Buffer.byteLength(text) <= ENVELOPE_LIMIT) return text;
    if (body._transport.assistant_text) {
      delete body._transport.assistant_text;
      body._truncated = true;
      text = encode();
      if (text === null) return null;
      if (Buffer.byteLength(text) <= ENVELOPE_LIMIT) return text;
    }
    body._raw = { header: {}, event: { type: body._raw?.event?.type || "" } };
    body._truncated = true;
    text = encode();
    if (text === null || Buffer.byteLength(text) > ENVELOPE_LIMIT) return null;
    return text;
  }

  
  function needsSessionInfo(info) {
    if (!info?.id || fetchedInfo.has(info.id)) return false;
    if (!info.directory || !info.title) return true;
    return !(info.parentID || info.parentId || info.parent_id);
  }

  async function ensureSessionInfo(ev) {
    if (ev.type !== "session.created" && ev.type !== "session.updated") return false;
    const info = ev.properties?.info;
    if (!needsSessionInfo(info)) return false;
    const fetched = await fetchSessionInfo(info.id, info.directory);
    if (!fetched) return false;
    fetchedInfo.set(info.id, fetched);
    if (fetchedInfo.size > 200) fetchedInfo.delete(fetchedInfo.keys().next().value);
    rememberSessionCwd(fetched);
    return true;
  }

  
  const termProg = process.env.TERM_PROGRAM || "";
  const needsTitleFallback = ["ghostty", "xterm-ghostty"].includes(termProg)
    && process.env.__CFBundleIdentifier === "com.mitchellh.ghostty"
    && !process.env.TMUX;
  const terminalTitlePreference = `${require("os").homedir()}/.vibe-island/cache/terminal-title-management`;
  let displayTitle = null;

  function managesTerminalTitles() {
    try { return require("fs").readFileSync(terminalTitlePreference, "utf8").trim() !== "0"; }
    catch { return true; }
  }

  function setTabTitle(sessionId, cwd, text) {
    if (!needsTitleFallback || !managesTerminalTitles()) return;
    const project = (cwd || directory || process.env.PWD || "session").split("/").pop() || "session";
    const prefix = String(sessionId).slice(0, 16);
    if (text) displayTitle = text.replace(/\n/g, " ").slice(0, 30);
    const title = displayTitle
      ? `${project} · ${displayTitle} · ${prefix}`
      : `${project} · ${prefix}`;
    if (detectedTty) {
      try { require("fs").writeFileSync(detectedTty, `\x1b]2;${title}\x07`); } catch {}
    }
    try {
      const fs = require("fs");
      const osc2Dir = `${require("os").homedir()}/.vibe-island/cache/osc2-titles`;
      try { fs.mkdirSync(osc2Dir, { recursive: true }); } catch {}
      fs.writeFileSync(`${osc2Dir}/${prefix}`, displayTitle || "");
    } catch {}
  }

  function noteTitleAnchor(ev) {
    const p = ev.properties || {};
    if (ev.type === "session.created" && p.info?.id) {
      setTabTitle(p.info.id, p.info.directory, null);
      return;
    }
    if (ev.type === "session.updated" && p.info?.id) {
      const title = p.info.title;
      if (title && !title.startsWith("New session")) setTabTitle(p.info.id, p.info.directory, title);
    }
  }

  const awaitLedger = new Map();

  function askedLedgerKey(ev) {
    const id = ev.properties?.id || ev.properties?.requestID || ev.id || "";
    return `${sessionOf(ev)}:${id}`;
  }

  function awaitEnvelope(ev) {
    const body = envelope(ev, false, false);
    if (!body) return null;
    const crypto = require("crypto");
    const key = (crypto.randomUUID ? crypto.randomUUID() : crypto.randomBytes(16).toString("hex"))
      .replace(/-/g, "");
    body._vibe_wire = 2;
    body._await = { key, deadline_ms: 300000 };
    return body;
  }

  function releaseAwaitIfOpen(event, state) {
    const key = askedLedgerKey(event);
    const entry = awaitLedger.get(key);
    if (!entry?.handle) return;
    entry.handle.release(state);
    awaitLedger.set(key, { claimed: true, settle: state });
  }

  async function dispatchAsked(event) {
    const body = awaitEnvelope(event);
    if (!body) return;
    const key = askedLedgerKey(event);
    const prior = awaitLedger.get(key);
    if (prior?.settle) {
      const replay = await sendAwaitAndWaitReply(body);
      if (replay && !replay.released) {
        replay.settle(prior.settle);
        replay.close();
      }
      return;
    }
    if (prior?.claimed) return;
    const waiter = startAwaitWaiter(body);
    awaitLedger.set(key, { claimed: true, handle: waiter.handle });
    const awaitSession = await waiter.promise;
    if (awaitSession?.released) {
      if (!awaitLedger.get(key)?.settle) {
        awaitLedger.set(key, { claimed: true, settle: awaitSession.state || "canceled" });
      }
      return;
    }
    if (!awaitSession) {
      awaitLedger.delete(key);
      return;
    }
    // 岛先答：立刻丢掉 handle，避免 permission.replied 回声把已收到的 _reply 再 cancel。
    awaitLedger.set(key, { claimed: true });
    const deliver = awaitSession.reply?.deliver;
    const cwd = sessionCwd.get(sessionOf(event)) || directory;
    let state = "failed";
    if (deliver?.mode === "post" && typeof deliver.origin_path === "string") {
      const posted = await postReply(deliver.origin_path, deliver.body ?? {}, cwd);
      state = posted ? "delivered" : "failed";
    } else if (deliver?.mode === "respond") {
      state = "delivered";
    }
    awaitLedger.set(key, { claimed: true, settle: state });
    awaitSession.settle(state);
    awaitSession.close();
  }

  async function dispatchEvent(event) {
    if (!event || !shouldProcessEvent(event)) return;
    if (APPROVAL_TYPES.has(event.type)) {
      if (event.type === "permission.asked" || event.type === "question.asked") {
        void dispatchAsked(event);
        return;
      }
      if (
        event.type === "permission.replied"
        || event.type === "question.replied"
        || event.type === "question.rejected"
      ) {
        releaseAwaitIfOpen(event, "canceled");
      }
      return;
    }
    if (!isObserved(event.type)) return;
    if (event.type === "message.part.delta") {
      absorbDelta(event.properties);
      return;
    }
    noteTitleAnchor(event);
    rememberSessionCwd(event.properties?.info);
    
    await emitEnvelope(event, false);
    
    if (await ensureSessionInfo(event)) await emitEnvelope(event, true);
  }

  async function emitEnvelope(event, hydration) {
    const body = envelope(event, wantsSnapshot(event), hydration);
    if (!body) return;
    const text = serializeEnvelope(body);
    if (text === null) return;
    
    if (isSyncDelivery(event)) {
      if (sendTextToSocketSync(text)) return;
      
      body._transport.sync_fallback = true;
      const retry = serializeEnvelope(body);
      if (retry !== null) { await sendTextToSocket(retry); return; }
    }
    await sendTextToSocket(text);
  }

  function shouldConsumeGlobalEvent(globalEvent) {
    if (!globalEvent?.payload) return false;
    if (globalEvent.directory && directory && globalEvent.directory !== directory) return false;
    return true;
  }

  function handleGlobalSseChunk(chunk) {
    const data = chunk.split(/\r?\n/)
      .filter((line) => line.startsWith("data:"))
      .map((line) => line.slice(5).trimStart())
      .join("\n");
    if (!data) return;
    try {
      const globalEvent = JSON.parse(data);
      if (!shouldConsumeGlobalEvent(globalEvent)) return;
      const payload = globalEvent.payload || {};
      if (payload.type !== "sync") return;
      const event = syncEventToBusEvent(payload.syncEvent);
      if (event) void dispatchEvent(event);
    } catch {}
  }

  
  async function startGlobalEventBridge() {
    const shouldStart = _VI_GLOBAL_EVENT_BRIDGE === "always"
      || process.env[`${_VI_ENV_PREFIX}_CLIENT`] === "desktop"
      || Boolean(_AUTH_HEADER)
      || (serverUrl?.port && serverPort !== 4096);
    if (!shouldStart) return;

    const bridgeDelay = (ms) => new Promise((resolve) => {
      const timer = setTimeout(resolve, ms);
      if (timer?.unref) timer.unref();
    });

    let delay = 1000;
    while (true) {
      try {
        const response = await fetch(`${serverOrigin}/global/event`, {
          method: "GET",
          headers: buildHeaders(directory),
        });
        if (!response?.ok || !response.body) throw new Error("global event unavailable");
        delay = 1000;
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";
        while (true) {
          const { value, done } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });
          buffer = buffer.replace(/\r\n/g, "\n");
          let idx;
          while ((idx = buffer.indexOf("\n\n")) !== -1) {
            const chunk = buffer.slice(0, idx);
            buffer = buffer.slice(idx + 2);
            handleGlobalSseChunk(chunk);
          }
        }
      } catch {}
      await bridgeDelay(delay);
      delay = Math.min(delay * 2, 30000);
    }
  }

  void startGlobalEventBridge();

  return {
    "event": async ({ event }) => {
      await dispatchEvent(event);
    },
    "shell.env": async (input, output) => {
      for (const v of ENV_KEYS) {
        if (process.env[v]) output.env["_VI_" + v] = process.env[v];
      }
    },
  };
};